16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.Period;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    @Email
67	    private String email;
68	
69	    @Column(name = "registration_date", columnDefinition = "DATE")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date", columnDefinition = "DATE")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "membership_number")
79	    private String membershipNumber;
80	
81	    @Column(name = "household_id")
82	    private String householdId;
83	
84	    @Column(name = "namesake_count")
85	    private Integer namesakeCount;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private boolean bulkSignupWarning;
89	
90	    @Column(name = "household_member_count")
91	    private Integer householdMemberCount;
92	
93	    @Column(name = "possible_duplicate")
94	    private boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
100	    private Set<Pet> pets;
101	
102	    /**
103	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
104	     * another owner already shares the same last name and address. Never persisted or returned.
105	     */
106	    @Transient
107	    private boolean sharesHousehold;
108	
109	    public String getTitle() {
110	        return this.title;
111	    }
112	
113	    public void setTitle(String title) {
114	        this.title = title;
115	    }
116	
117	    /**
118	     * Derive the owner's read-only {@code salutation}: the honorific {@code title} and
119	     * {@code lastName} joined by a single space ({@code '<title> <lastName>'}) when a title has
120	     * been supplied, otherwise just the {@code lastName}. A {@code null} or blank title yields the
121	     * bare last name.
122	     */
123	    @Transient
124	    public String getSalutation() {
125	        if (this.title == null || this.title.isBlank()) {
126	            return getLastName();
127	        }
128	        return this.title + " " + getLastName();
129	    }
130	
131	    public String getAddress() {
132	        return this.address;
133	    }
134	
135	    public void setAddress(String address) {
136	        this.address = address;
137	    }
138	
139	    public String getAddressLine1() {
140	        return this.addressLine1;
141	    }
142	
143	    public void setAddressLine1(String addressLine1) {
144	        this.addressLine1 = addressLine1;
145	    }
146	
147	    public String getAddressLine2() {
148	        return this.addressLine2;
149	    }
150	
151	    public void setAddressLine2(String addressLine2) {
152	        this.addressLine2 = addressLine2;
153	    }
154	
155	    public String getCity() {
156	        return this.city;
157	    }
158	
159	    public void setCity(String city) {
160	        this.city = city;
161	    }
162	
163	    public String getPostcode() {
164	        return this.postcode;
165	    }
166	
167	    public void setPostcode(String postcode) {
168	        this.postcode = postcode;
169	    }
170	
171	    public String getTelephone() {
172	        return this.telephone;
173	    }
174	
175	    public void setTelephone(String telephone) {
176	        this.telephone = telephone;
177	    }
178	
179	    public String getEmail() {
180	        return this.email;
181	    }
182	
183	    public void setEmail(String email) {
184	        this.email = email;
185	    }
186	
187	    public LocalDate getRegistrationDate() {
188	        return this.registrationDate;
189	    }
190	
191	    public void setRegistrationDate(LocalDate registrationDate) {
192	        this.registrationDate = registrationDate;
193	    }
194	
195	    public LocalDate getBirthDate() {
196	        return this.birthDate;
197	    }
198	
199	    public void setBirthDate(LocalDate birthDate) {
200	        this.birthDate = birthDate;
201	    }
202	
203	    /**
204	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
205	     * owner's {@code registrationDate} (falling back to the current date when no registration date
206	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
207	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
208	     */
209	    @Transient
210	    public String getAgeBand() {
211	        if (this.birthDate == null) {
212	            return null;
213	        }
214	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
215	        int age = Period.between(this.birthDate, reference).getYears();
216	        if (age < 18) {
217	            return "MINOR";
218	        }
219	        if (age < 65) {
220	            return "ADULT";
221	        }
222	        return "SENIOR";
223	    }
224	
225	    public String getCustomerCode() {
226	        return this.customerCode;
227	    }
228	
229	    public void setCustomerCode(String customerCode) {
230	        this.customerCode = customerCode;
231	    }
232	
233	    public String getMembershipNumber() {
234	        return this.membershipNumber;
235	    }
236	
237	    public void setMembershipNumber(String membershipNumber) {
238	        this.membershipNumber = membershipNumber;
239	    }
240	
241	    public String getHouseholdId() {
242	        return this.householdId;
243	    }
244	
245	    public void setHouseholdId(String householdId) {
246	        this.householdId = householdId;
247	    }
248	
249	    public Integer getNamesakeCount() {
250	        return this.namesakeCount;
251	    }
252	
253	    public void setNamesakeCount(Integer namesakeCount) {
254	        this.namesakeCount = namesakeCount;
255	    }
256	
257	    /**
258	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
259	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
260	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
261	     * the owner's tenure exceeds 365 days (measured from the {@code registrationDate} to today).
262	     */
263	    @Transient
264	    public Integer getMembershipPoints() {
265	        int points = 0;
266	        if (this.email != null && !this.email.isBlank()) {
267	            points += 2;
268	        }
269	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
270	            points += 1;
271	        }
272	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
273	            points += 2;
274	        }
275	        if (hasTenureOver365Days()) {
276	            points += 3;
277	        }
278	        return points;
279	    }
280	
281	    /**
282	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
283	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
284	     * points, and level 4 for 6 or more points.
285	     */
286	    @Transient
287	    public Integer getMembershipLevel() {
288	        int points = getMembershipPoints();
289	        if (points <= 1) {
290	            return 1;
291	        }
292	        if (points <= 3) {
293	            return 2;
294	        }
295	        if (points <= 5) {
296	            return 3;
297	        }
298	        return 4;
299	    }
300	
301	    /**
302	     * Whether the owner's tenure, measured as the number of whole days from {@code registrationDate}
303	     * to today, exceeds 365 days — worth 3 membership points. A missing {@code registrationDate}
304	     * (and therefore zero tenure) never qualifies.
305	     */
306	    @Transient
307	    private boolean hasTenureOver365Days() {
308	        if (this.registrationDate == null) {
309	            return false;
310	        }
311	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
312	    }
313	
314	    /**
315	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
316	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
317	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
318	     * has been assigned yet.
319	     */
320	    @Transient
321	    public Integer getCheckDigit() {
322	        if (this.customerCode == null) {
323	            return null;
324	        }
325	        int sum = 0;
326	        boolean dbl = true;
327	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
328	            char c = this.customerCode.charAt(i);
329	            if (c < '0' || c > '9') {
330	                continue;
331	            }
332	            int d = c - '0';
333	            if (dbl) {
334	                d *= 2;
335	                if (d > 9) {
336	                    d -= 9;
337	                }
338	            }
339	            sum += d;
340	            dbl = !dbl;
341	        }
342	        return (10 - (sum % 10)) % 10;
343	    }
344	
345	    /**
346	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
347	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
348	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
349	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
350	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
351	     */
352	    @Transient
353	    public String getIdentityKey() {
354	        String telephonePart = this.telephone == null ? "" : this.telephone;
355	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
356	        String householdPart = this.householdId == null ? "" : this.householdId;
357	        return telephonePart + "|" + emailPart + "|" + householdPart;
358	    }
359	
360	    public boolean isBulkSignupWarning() {
361	        return this.bulkSignupWarning;
362	    }
363	
364	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
365	        this.bulkSignupWarning = bulkSignupWarning;
366	    }
367	
368	    public Integer getHouseholdMemberCount() {
369	        return this.householdMemberCount;
370	    }
371	
372	    public void setHouseholdMemberCount(Integer householdMemberCount) {
373	        this.householdMemberCount = householdMemberCount;
374	    }
375	
376	    /**
377	     * Whether this owner was flagged at creation as a possible (soft) duplicate: it is not a hard
378	     * {@code identityKey} duplicate, but shares an existing owner's last name and postcode while
379	     * carrying a different telephone. The owner is still created; this flag is advisory.
380	     */
381	    public boolean isPossibleDuplicate() {
382	        return this.possibleDuplicate;
383	    }
384	
385	    public void setPossibleDuplicate(boolean possibleDuplicate) {
386	        this.possibleDuplicate = possibleDuplicate;
387	    }
388	
389	    /**
390	     * The id of the existing owner this one soft-matched against (same last name and postcode,
391	     * different telephone), or {@code null} when {@link #isPossibleDuplicate()} is {@code false}.
392	     */
393	    public Integer getPossibleDuplicateOf() {
394	        return this.possibleDuplicateOf;
395	    }
396	
397	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
398	        this.possibleDuplicateOf = possibleDuplicateOf;
399	    }
400	
401	    public boolean isSharesHousehold() {
402	        return this.sharesHousehold;
403	    }
404	
405	    public void setSharesHousehold(boolean sharesHousehold) {
406	        this.sharesHousehold = sharesHousehold;
407	    }
408	
409	    protected Set<Pet> getPetsInternal() {
410	        if (this.pets == null) {
411	            this.pets = new HashSet<>();
412	        }
413	        return this.pets;
414	    }
415	
416	    protected void setPetsInternal(Set<Pet> pets) {
417	        this.pets = pets;
418	    }
419	
420	    public List<Pet> getPets() {
421	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
422	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
423	        return Collections.unmodifiableList(sortedPets);
424	    }
425	
426	    public void setPets(List<Pet> pets) {
427	        this.pets = new HashSet<>(pets);
428	    }
429	
430	    public void addPet(Pet pet) {
431	        getPetsInternal().add(pet);
432	        pet.setOwner(this);
433	    }
434	
435	    /**
436	     * Return the Pet with the given name, or null if none found for this Owner.
437	     *
438	     * @param name to test
439	     * @return true if pet name is already in use
440	     */
441	    public Pet getPet(String name) {
442	        return getPet(name, false);
443	    }
444	
445	    /**
446	     * Return the Pet with the given name, or null if none found for this Owner.
447	     *
448	     * @param name to test
449	     * @return true if pet name is already in use
450	     */
451	    public Pet getPet(String name, boolean ignoreNew) {
452	        name = name.toLowerCase();
453	        for (Pet pet : getPetsInternal()) {
454	            if (!ignoreNew || !pet.isNew()) {
455	                String compName = pet.getName();
456	                compName = compName.toLowerCase();
457	                if (compName.equals(name)) {
458	                    return pet;
459	                }
460	            }
461	        }
462	        return null;
463	    }
464	
465	    public Pet getPet(Integer petId) {
466	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
467	    }
468	
469	    @Override
470	    public String toString() {
471	        return new ToStringCreator(this)
472	
473	            .append("id", this.getId())
474	            .append("new", this.isNew())
475	            .append("lastName", this.getLastName())
476	            .append("firstName", this.getFirstName())
477	            .append("address", this.address)
478	            .append("city", this.city)
479	            .append("telephone", this.telephone)
480	            .toString();
481	    }
482	}
