252	    @Override
253	    @Transactional
254	    public void saveOwner(Owner owner) throws DataAccessException {
255	        boolean isNew = owner.isNew();
256	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
257	        // roll it forward to the next business day so it never lands on a weekend. Everything
258	        // derived from the registration date below must use this adjusted value.
259	        LocalDate registrationDate = toBusinessDay(
260	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
261	        owner.setRegistrationDate(registrationDate);
262	        // Whether this owner was accepted into an existing household because the request declared it
263	        // shares one (sharesHousehold). A declared member is deliberately not treated as a suspected
264	        // duplicate below.
265	        boolean declaredHouseholdMember = false;
266	        if (owner.isNew()) {
267	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
268	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
269	            // it automatically. It is part of the owner's identityKey, so it is resolved first.
270	            owner.setHouseholdId(computeHouseholdId(owner));
271	            // The household is keyed on (last name, postcode), so the members are the existing owners
272	            // sharing both with this owner.
273	            List<Owner> householdMembers = findHouseholdMembers(owner);
274	            // Size of the household after this create: the existing members plus this new owner.
275	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
276	            // A second owner in an existing household is the same household and is rejected as a
277	            // household duplicate, UNLESS the request declares (via sharesHousehold) that it genuinely
278	            // shares the household. sharesHousehold only bypasses this block; it no longer creates the
279	            // link, which is now derived from (last name, postcode).
280	            if (!householdMembers.isEmpty()) {
281	                if (!owner.isSharesHousehold()) {
282	                    throw new HouseholdDuplicateException(owner.getHouseholdId());
283	                }
284	                declaredHouseholdMember = true;
285	            }
286	        }
287	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
288	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
289	        // subsumes the former separate telephone, email and household checks.
290	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
291	            throw new DuplicateIdentityException(owner.getIdentityKey());
292	        }
293	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
294	        // postcode while carrying a different telephone. Still created, but flagged as a possible
295	        // duplicate pointing at the matching owner. A declared household member is not a suspected
296	        // duplicate, so it is never flagged.
297	        if (owner.isNew() && !declaredHouseholdMember) {
298	            Owner softMatch = findPossibleDuplicate(owner);
299	            if (softMatch != null) {
300	                owner.setPossibleDuplicate(true);
301	                owner.setPossibleDuplicateOf(softMatch.getId());
302	            }
303	        }
304	        if (owner.isNew()
305	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
306	            throw new CityOwnerLimitExceededException(owner.getCity());
307	        }
308	        if (owner.isNew()
309	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
310	            throw new DailyOwnerLimitExceededException(registrationDate);
311	        }
312	        if (owner.isNew() && owner.getCustomerCode() == null) {
313	            owner.setCustomerCode(generateCustomerCode(owner));
314	        }
315	        if (owner.isNew()) {
316	            owner.setNamesakeCount(countNamesakes(owner));
317	            owner.setBulkSignupWarning(
318	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
319	        }
320	        if (owner.getMembershipNumber() == null) {
321	            owner.setMembershipNumber(generateMembershipNumber(owner));
322	        }
323	        ownerRepository.save(owner);
324	        if (isNew) {
325	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
326	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
327	                owner.getMembershipNumber(), owner.getRegistrationDate());
328	        }
329	    }
330	
331	    /**
332	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
333	     * owner. The key consolidates telephone, email and household into one value, so two owners
334	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
335	     * the owner's {@code householdId} has been resolved, so its key is complete.
336	     */
337	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
338	        String identityKey = owner.getIdentityKey();
339	        return ownerRepository.findAll().stream()
340	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
341	    }
342	
343	    /**
344	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
345	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
346	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
347	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
348	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
349	     */
350	    private Owner findPossibleDuplicate(Owner owner) {
351	        String key = householdKey(owner);
352	        if (key == null) {
353	            return null;
354	        }
355	        String telephone = owner.getTelephone();
356	        return ownerRepository.findAll().stream()
357	            .filter(existing -> key.equals(householdKey(existing))
358	                && !Objects.equals(telephone, existing.getTelephone()))
359	            .min(Comparator.comparing(Owner::getId))
360	            .orElse(null);
361	    }
362	
363	    /**
364	     * Count the owners that already exist (before this create) sharing the same first name and last
365	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
366	     * unique among the existing owners.
367	     */
368	    private int countNamesakes(Owner owner) {
369	        String firstName = owner.getFirstName();
370	        String lastName = owner.getLastName();
371	        if (firstName == null || lastName == null) {
372	            return 0;
373	        }
374	        return (int) ownerRepository.findAll().stream()
375	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
376	                && lastName.equalsIgnoreCase(existing.getLastName()))
377	            .count();
378	    }
379	
380	    /**
381	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
382	     * last name and its postcode. Last names are compared case-insensitively with collapsed
383	     * whitespace; postcodes are compared exactly. This is the same keying used by
384	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
385	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
386	     * postcode to match on.
387	     */
388	    private List<Owner> findHouseholdMembers(Owner owner) {
389	        String key = householdKey(owner);
390	        if (key == null) {
391	            return List.of();
392	        }
393	        return ownerRepository.findAll().stream()
394	            .filter(existing -> key.equals(householdKey(existing)))
395	            .toList();
396	    }
397	
398	    /**
399	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
400	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
401	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
402	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
403	     * postcode, so it does not belong to a shared household.
404	     */
405	    private String computeHouseholdId(Owner owner) {
406	        String key = householdKey(owner);
407	        return key == null ? null : sha256Hex(key, 6, false);
408	    }
409	
410	    /**
411	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
412	     * that identifies a household. The last name is normalized case-insensitively with collapsed
413	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
414	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
415	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
416	     * cannot drift apart.
417	     */
418	    private String householdKey(Owner owner) {
419	        String lastName = normalizeHouseholdKey(owner.getLastName());
420	        String postcode = owner.getPostcode();
421	        if (lastName == null || postcode == null || postcode.isBlank()) {
422	            return null;
423	        }
424	        return lastName + "|" + postcode;
425	    }
426	
427	    /**
428	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
429	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
430	     */
431	    private String normalizeHouseholdKey(String value) {
432	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
433	    }
434	
435	    /**
436	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
437	     * code resolved from the owner's postcode (falling back to the owner's city, else
438	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
439	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
440	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
441	     * derived from the owner's own attributes.
442	     * <p>
443	     * When the derived code collides with an existing owner's {@code customerCode}, a
444	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes it
445	     * unique, so distinct owners always receive distinct customer codes.
446	     */
447	    private String generateCustomerCode(Owner owner) {
448	        String base = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
449	        return deduplicateCustomerCode(base);
450	    }
451	
452	    /**
453	     * Return {@code base} when no existing owner already uses it as their {@code customerCode};
454	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
455	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
456	     */
457	    private String deduplicateCustomerCode(String base) {
458	        Set<String> existing = ownerRepository.findAll().stream()
459	            .map(Owner::getCustomerCode)
460	            .filter(Objects::nonNull)
461	            .collect(Collectors.toSet());
462	        if (!existing.contains(base)) {
463	            return base;
464	        }
465	        int n = 2;
466	        while (existing.contains(base + "-" + n)) {
467	            n++;
468	        }
469	        return base + "-" + n;
470	    }
471	
472	    /**
473	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
474	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
475	     * with the owner's last name.
476	     */
477	    private String customerHash(Owner owner) {
478	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
479	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
480	        return sha256Hex(telephone + lastName, 4, true);
481	    }
482	
483	    /**
484	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
485	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
486	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
487	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
488	     * digest handling and the "SHA-256 not available" error live in one place.
489	     */
490	    private String sha256Hex(String input, int bytes, boolean upperCase) {
491	        byte[] digest;
492	        try {
493	            digest = MessageDigest.getInstance("SHA-256")
494	                .digest(input.getBytes(StandardCharsets.UTF_8));
495	        } catch (NoSuchAlgorithmException e) {
496	            throw new IllegalStateException("SHA-256 is required but not available", e);
497	        }
498	        String format = upperCase ? "%02X" : "%02x";
499	        StringBuilder hex = new StringBuilder(bytes * 2);
500	        for (int i = 0; i < bytes; i++) {
501	            hex.append(String.format(format, digest[i]));
502	        }
503	        return hex.toString();
504	    }
505	
506	    /**
507	     * Count the owners that already exist (before this create) in the same city as {@code owner},
508	     * compared case-insensitively.
509	     */
510	    private long countOwnersInCity(Owner owner) {
511	        String city = owner.getCity();
512	        return ownerRepository.findAll().stream()
513	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
514	            .count();
515	    }
516	
517	    /**
518	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
519	     * on the given {@code date}. Used to enforce the per-day create cap.
520	     */
521	    private long countOwnersRegisteredOn(LocalDate date) {
522	        return ownerRepository.findAll().stream()
523	            .filter(existing -> date.equals(existing.getRegistrationDate()))
524	            .count();
525	    }
526	
527	    /**
528	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
529	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
530	     * are required to fall on a business day.
531	     */
532	    private LocalDate toBusinessDay(LocalDate date) {
533	        switch (date.getDayOfWeek()) {
534	            case SATURDAY:
535	                return date.plusDays(2);
536	            case SUNDAY:
537	                return date.plusDays(1);
538	            default:
539	                return date;
540	        }
541	    }
542	
543	    /**
544	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
545	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
546	     */
547	    private String generateMembershipNumber(Owner owner) {
548	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
549	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
550	    }
551	
