568	    }
569	
570	    private <T> T findEntityById(Supplier<T> supplier) {
571	        try {
572	            return supplier.get();
573	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
574	            // Just ignore not found exceptions for Jdbc/Jpa realization
575	            return null;
576	        }
577	    }
578	
579	}
