1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.PostcodeRules;
14	import org.springframework.samples.petclinic.util.RegionTimezones;
15	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
16	
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
27	    @Mapping(target = "salutation", expression = "java(owner.getSalutation())")
28	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
29	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
30	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
32	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derive the owner's read-only {@code telephoneDisplay}: the stored E.164 {@code telephone}
38	     * formatted for humans (country code, a space, then the national digits grouped in threes),
39	     * e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}. Returns {@code null} when the
40	     * owner has no telephone, so the field is omitted from the response.
41	     */
42	    default String toTelephoneDisplay(Owner owner) {
43	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
44	    }
45	
46	    /**
47	     * Derive the owner's read-only {@code ageBand} enum from its {@code birthDate}, computed against
48	     * the owner's {@code registrationDate} (see {@link Owner#getAgeBand()}). Returns {@code null}
49	     * when the owner has no {@code birthDate}, so the field is omitted from the response.
50	     */
51	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
52	        String ageBand = owner.getAgeBand();
53	        return ageBand == null ? null : OwnerDto.AgeBandEnum.fromValue(ageBand);
54	    }
55	
56	    /**
57	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
58	     * read-only {@code displayName} field returned on the Owner DTO.
59	     */
60	    default String toDisplayName(Owner owner) {
61	        return owner.getLastName() + ", " + owner.getFirstName();
62	    }
63	
64	    /**
65	     * Build the owner's initials as the upper-cased first letters of firstName and
66	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
67	     * read-only {@code initials} field returned on the Owner DTO.
68	     */
69	    default String toInitials(Owner owner) {
70	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
71	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
72	    }
73	
74	    /**
75	     * Derive the owner's read-only {@code locality}: the REGION segment of the owner's
76	     * {@code customerCode} ({@code '<REGION>-<HASH8>'}), the region-and-hash identity the owner is
77	     * assigned at creation. Falls back to resolving the region directly from the owner's postcode
78	     * range first ({@code NSW 2000-2099, VIC 3000-3099, QLD 4000-4099}), then the canonical region
79	     * of the owner's city ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), else {@code 'UNKNOWN'},
80	     * when the owner has no {@code customerCode} yet. Sourcing it from the identity keeps the
81	     * owner's reported locality and its {@code customerCode} region in lock-step.
82	     */
83	    default String toLocality(Owner owner) {
84	        String customerCode = owner.getCustomerCode();
85	        if (customerCode != null) {
86	            int dash = customerCode.indexOf('-');
87	            if (dash > 0) {
88	                return customerCode.substring(0, dash);
89	            }
90	        }
91	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity());
92	    }
93	
94	    /**
95	     * Derive the owner's read-only {@code timezone}: the IANA timezone name for the owner's
96	     * locality/region, looked up from the fixed region-to-timezone table ({@code NSW->Australia/Sydney,
97	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane}). The region is the same value reported as the
